int solve(vector<int>& cost, int idx) {
        int n = cost.size();
        if (n == 0) return 0;

        vector<int> dp(n + 2, 0);

        for (int i = n - 1; i >= 0; --i) {
            int move_one = cost[i] + dp[i + 1];
            int move_two = (i + 2 <= n) ? (cost[i] + dp[i + 2]) : cost[i];
            dp[i] = min(move_one, move_two);
        }

        return dp[idx];
    }

