int solve(int parent, int n, int k){
    int current_parent = parent;
    int current_n = n;
    int current_k = k;

    while (current_n > 0) {
        int mid = 1 << (current_n - 1);
        if (current_k < mid) {
            current_parent = (current_parent == 0 ? 0 : 1);
        } else {
            current_parent = (current_parent == 0 ? 1 : 0);
            current_k -= mid;
        }
        current_n -= 1;
    }
    return current_parent;
}
